import { IconCaretDown, IconCaretUp } from '@hawkins/assets';
import {
    Button,
    type DropdownBaseProps,
    type DropdownOption,
    type DropdownTriggerType,
    Text,
    Tooltip,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { type ForwardedRef, forwardRef, useRef } from 'react';

type DropdownTriggerProps<T extends DropdownOption> = DropdownBaseProps<T> &
    DropdownTriggerType<T, string> & {
        hideSubtitle?: boolean;
        labelMaxWidth?: number;
        titleMaxWidth?: number;
        subtitleMaxWidth?: number;
    };

export const DropdownTrigger = forwardRef(
    <T extends DropdownOption>(
        {
            onClick,
            onKeyDown,
            selected,
            loading,
            hideSubtitle = false,
            labelMaxWidth = 150,
            titleMaxWidth = 150,
            subtitleMaxWidth = 150,
            getOptionSubtitle,
            placeholder = 'Select Option',
            disabled,
            style,
            ...props
        }: DropdownTriggerProps<T>,
        ref: ForwardedRef<HTMLElement>,
    ) => {
        const titleRef = useRef(null);
        const subTitleRef = useRef(null);
        const showPlaceholder = !loading && Array.isArray(selected) && selected.length === 0;
        const title = loading
            ? 'loading...'
            : Array.isArray(selected)
              ? showPlaceholder
                  ? placeholder
                  : `${selected[0]?.label ?? ''} ${selected.length > 1 ? `[+${selected.length - 1}]` : ''}`
              : '';
        const subtitle =
            getOptionSubtitle && selected
                ? getOptionSubtitle(Array.isArray(selected) ? selected[0] : selected)
                : undefined;

        return (
            <Button
                onClick={onClick}
                onKeyDown={onKeyDown}
                ref={ref}
                variant='tertiary'
                disabled={disabled}
                className={disabled ? 'sr-dropdown-disabled' : undefined}
                style={{ ...style, padding: `${Dimensions.Space6} ${Dimensions.Space8}` }}
            >
                <div style={{ display: 'flex', flexDirection: 'column', flex: 1 }}>
                    <Text
                        align='left'
                        variant='label'
                        colorVariant='faded'
                        noWrap
                        style={{ maxWidth: labelMaxWidth }}
                        component='div'
                    >
                        {props.label}
                    </Text>
                    <div style={{ display: 'flex', alignItems: 'center', flex: 1, gap: 5 }}>
                        <Tooltip label={title} ref={titleRef} ellipsis>
                            <Text
                                ref={titleRef}
                                noWrap
                                style={{ maxWidth: titleMaxWidth }}
                                colorVariant={showPlaceholder ? 'faded' : undefined}
                            >
                                {title}
                            </Text>
                        </Tooltip>
                        {!hideSubtitle && subtitle && (
                            <Tooltip label={subtitle} ref={subTitleRef} ellipsis>
                                <Text
                                    ref={subTitleRef}
                                    colorVariant='faded'
                                    noWrap
                                    style={{ maxWidth: subtitleMaxWidth }}
                                    dir='rtl'
                                >
                                    <bdi>{subtitle}</bdi>
                                </Text>
                            </Tooltip>
                        )}
                        <div style={{ flex: 1 }} />
                        {props.open ? <IconCaretUp size='small' /> : <IconCaretDown size='small' />}
                    </div>
                </div>
            </Button>
        );
    },
) as <T extends DropdownOption>(props: DropdownTriggerProps<T> & { ref?: ForwardedRef<HTMLElement> }) => JSX.Element;
